#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;
int main() {
    int rounds; cin >> rounds;
    while (rounds--) {
        int familySize; cin >> familySize;
        vector<int> streets(familySize);
        for (int k = 0; k < familySize; ++k) cin >> streets[k];
        int meeting = streets[0];
        int cost = 0;
        for (int k = 0; k < familySize; ++k) cost += abs(streets[k] - meeting);
        cout << cost << '\n';
    }
}

